// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette{value: 10 ether}(); }

    // fuzz the caller and the amount sent. The distinguishing property is about which msg.value is accepted.
    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        // keep caller non-zero to be a sensible actor
        vm.assume(caller != address(0));
        // bound amount to something reasonable so fuzz explores relevant domain
        amount = bound(amount, 0, 20 ether);

        // fund the caller so it can send ether
        vm.deal(caller, amount);

        // record pastBlockTime before the call
        uint256 before = c.pastBlockTime();

        // perform the low-level call to trigger fallback
        bool ok;
        vm.prank(caller);
        // using address(c).call to trigger fallback payable
        (ok, ) = address(c).call{value: amount}("");

        uint256 after_ = c.pastBlockTime();

        // General rule (single assert): For the reference contract, any successful fallback call must have been made with exactly 10 ether;
        // therefore when the call succeeded, pastBlockTime must have advanced (strictly greater) AND the sent amount must be 10 ether.
        // We assert a property the reference always satisfies: if the call succeeded then (amount == 10 ether && after > before).
        // The mutant that accepts 5 ether will allow a successful call with amount == 5 ether, violating this assertion for some fuzzed input.
        if (ok) {
            // exactly one assertion required by the harness
            assertTrue(amount == 10 ether && after_ > before);
        } else {
            // if the call reverted, ensure pastBlockTime did not change (reference: require reverts before updating state)
            assertTrue(after_ == before);
        }
    }
}
